"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["4749"],{40304(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.peso_area_enem.par_ja_existe","status":409,"titulo":"J\xe1 existe uma linha de pesos ativa para esta resolu\xe7\xe3o e grupo de curso"},"descricao":{"codigo":"uniplus.configuracao.peso_area_enem.par_ja_existe","requisitos":[],"oQueAconteceu":["O cadastro (`POST /api/configuracao/admin/pesos-area-enem`) trouxe uma resolu\xe7\xe3o e um grupo de \xe1rea do ENEM para os quais j\xe1 existe uma linha de pesos. Cada resolu\xe7\xe3o, como a Resolu\xe7\xe3o n\xba 805/2024/Consepe, da Unifesspa, tem uma linha por grupo de \xe1rea, e a combina\xe7\xe3o \xe9 \xfanica entre as linhas existentes. A resolu\xe7\xe3o \xe9 comparada depois de aparada e normalizada, e as mai\xfasculas e min\xfasculas contam. Duas requisi\xe7\xf5es simult\xe2neas com a mesma combina\xe7\xe3o tamb\xe9m terminam nesta recusa: a que confirma por \xfaltimo a recebe.","Esta confer\xeancia vem depois da confer\xeancia do corpo: com um corpo inv\xe1lido, a resposta \xe9 a recusa do corpo (422), e n\xe3o esta. Nada \xe9 gravado."],"comoResolver":["Para mudar os pesos, as notas de corte ou a base legal da linha que j\xe1 existe, atualize-a (`PUT /api/configuracao/admin/pesos-area-enem/{id}`); a resolu\xe7\xe3o e o grupo dela n\xe3o mudam. A linha \xe9 localizada na listagem (`GET /api/configuracao/pesos-area-enem`). Se a inten\xe7\xe3o era cadastrar os pesos de outra resolu\xe7\xe3o, informe a resolu\xe7\xe3o correta."],"ondeAparece":["Cadastro dos pesos por \xe1rea do ENEM"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Peso area enem"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);